DROP POLICY IF EXISTS "CMS users can insert events" ON public.events; DROP POLICY IF EXISTS "CMS users can update events" ON public.events; DROP POLICY IF EXISTS "CMS users can delete events" ON public.events; CREATE POLICY "CMS users can insert events" ON public.events FOR INSERT TO authenticated WITH CHECK (can_manage_content(auth.uid())); CREATE POLICY "CMS users can update events" ON public.events FOR UPDATE TO authenticated USING (can_manage_content(auth.uid())); CREATE POLICY "CMS users can delete events" ON public.events FOR DELETE TO authenticated USING (can_manage_content(auth.uid())); REVOKE EXECUTE ON FUNCTION public.is_admin(uuid) FROM PUBLIC, anon, authenticated; REVOKE EXECUTE ON FUNCTION public.is_editor(uuid) FROM PUBLIC, anon, authenticated; REVOKE EXECUTE ON FUNCTION public.can_manage_content(uuid) FROM PUBLIC, anon, authenticated; DROP POLICY IF EXISTS "Anyone can view site images bucket" ON storage.objects;